const lockUserPoints = `-- name: LockUserPoints :one
UPDATE users
SET locked_points_balance = locked_points_balance + $2
WHERE id = $1 AND (points_balance - locked_points_balance) >= $2
RETURNING id, points_balance, locked_points_balance
`

